#
# Regenerates test/fixtures/trim_fixture.h: a stream-copy-trimmed AAC mp4 (S10-1, step 10 of plan 869ejxng3),
# the shape of a file cut with `ffmpeg -ss … -c copy`: its first audio packets have negative pts and the first
# carries the AV_PKT_DATA_SKIP_SAMPLES of the cut. avformat_seek_file(INT64_MIN) lands on the SECOND packet on
# a fresh demux and at end of file after a full read, so the player's wrap seek failed on such files. Also
# embeds the decoded length with the skip applied (ffmpeg's own decode), the length every pass must have.
# Run from this directory on casas.
set -euo pipefail
cd "$(dirname "$0")"
T=$(mktemp -d); trap 'rm -rf "$T"' EXIT
F="ffmpeg -hide_banner -loglevel error -y"
BX="-fflags +bitexact -flags:a +bitexact"
$F -f lavfi -i "sine=f=440:d=1.5:sample_rate=48000,volume=-27dB" $BX -ac 1 -c:a aac -b:a 24k "$T/src.m4a"
$F -ss 0.52 -i "$T/src.m4a" -c copy $BX -f mp4 "$T/fx_trim_aac.mp4"
# the decoded length with the cut's skip applied (mono s16: 2 bytes per frame)
frames=$(( $($F -i "$T/fx_trim_aac.mp4" -f s16le -ac 1 - | wc -c) / 2 ))
OUT=trim_fixture.h
{
  echo "// SPDX-FileCopyrightText: 2026 Stagelab Coop SCCL"
  echo "// SPDX-License-Identifier: GPL-3.0-or-later"
  echo "// SPDX-FileContributor: Ion Reguera <ion@stagelab.coop>"
  echo "// Generated by test/fixtures/gen_trim.sh -- do not edit."
  echo "#pragma once"
  sz=$(stat -c %s "$T/fx_trim_aac.mp4"); [ "$sz" -le 20480 ] || { echo "fx_trim_aac.mp4 is $sz bytes (> 20 KB)" >&2; exit 1; }
  python3 -c 'import sys,re
p=sys.argv[1]; n=re.sub(r"[^A-Za-z0-9]","_",p.rsplit("/",1)[1]); d=open(p,"rb").read()
print("static const unsigned char %s[] = {" % n)
for i in range(0,len(d),12): print("  "+", ".join("0x%02x" % b for b in d[i:i+12])+",")
print("};"); print("static const unsigned int %s_len = %d;" % (n,len(d)))' "$T/fx_trim_aac.mp4"
  echo "static const long fx_trim_aac_mp4_decoded_frames = $frames;   // 48 kHz mono, skip applied"
} > "$OUT"
ls -la "$OUT"; echo "decoded frames $frames"
